package dev.by1337.virtualentity.api.virtual; import java.util.*;import org.by1337.blib.geom.Vec3d; public interface VirtualExperienceOrb extends VirtualEntity {void setValue(int v); static VirtualExperienceOrb create(){Orb o=new Orb();Orb.created.add(o);return o;} public static class Orb implements VirtualExperienceOrb {public static final List<Orb> created=new ArrayList<>();public int value,moves;public boolean noGravity,silent;public Vec3d pos;public void setNoGravity(boolean b){noGravity=b;}public void setSilent(boolean b){silent=b;}public void setPos(Vec3d v){pos=v;moves++;}public void setValue(int v){value=v;}}}
